const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const n = nextInt();
const xs = new Int32Array(n);
for (let i = 0; i < n; i++) xs[i] = nextInt();

const u = new Int32Array(n);
const v = new Int32Array(n);
let minU = Infinity, maxU = -Infinity;
let minV = Infinity, maxV = -Infinity;

for (let i = 0; i < n; i++) {
  const y = nextInt();
  u[i] = xs[i] + y;
  v[i] = xs[i] - y;
  if (u[i] < minU) minU = u[i];
  if (u[i] > maxU) maxU = u[i];
  if (v[i] < minV) minV = v[i];
  if (v[i] > maxV) maxV = v[i];
}

const orderU = new Array(n);
const orderV = new Array(n);
for (let i = 0; i < n; i++) {
  orderU[i] = i;
  orderV[i] = i;
}
orderU.sort((a, b) => u[a] - u[b]);
orderV.sort((a, b) => v[a] - v[b]);

const rankU = new Int32Array(n);
const rankV = new Int32Array(n);
for (let i = 0; i < n; i++) {
  rankU[orderU[i]] = i;
  rankV[orderV[i]] = i;
}

