const prevU = new Int32Array(n + 1);
const nextV = new Int32Array(n + 1);
const prevV = new Int32Array(n + 1);
const color = new Int8Array(n);
const queue = new Int32Array(n);

function find(parent, x) {
  let root = x;
  while (parent[root] !== root) root = parent[root];
  while (parent[x] !== x) {
    const next = parent[x];
    parent[x] = root;
    x = next;
  }
  return root;
}

function feasible(d) {
  if (maxU - minU <= d && maxV - minV <= d) return true;

  for (let i = 0; i <= n; i++) {
    nextU[i] = i;
    prevU[i] = i;
    nextV[i] = i;
    prevV[i] = i;
  }
  color.fill(-1);

  function removePoint(p) {
    const ru = rankU[p];
    const rv = rankV[p];
    nextU[ru] = find(nextU, ru + 1);
    prevU[ru + 1] = find(prevU, ru);
    nextV[rv] = find(nextV, rv + 1);
    prevV[rv + 1] = find(prevV, rv);
  }

  let head = 0;
  let tail = 0;

  for (let root = 0; root < n; root++) {
    if (color[root] !== -1) continue;

    color[root] = 0;
    queue[tail++] = root;
    removePoint(root);

    while (head < tail) {
      const p = queue[head++];
      const cu = u[p];
      const cv = v[p];
      const opposite = 1 - color[p];

      while (true) {
        let q = -1;
        let r = find(nextU, 0);

        if (r < n) {
          const candidate = orderU[r];
          if (u[candidate] < cu - d) q = candidate;
        }

        if (q === -1) {
          r = find(prevU, n);
          if (r > 0) {
            const candidate = orderU[r - 1];
            if (u[candidate] > cu + d) q = candidate;
          }
        }

        if (q === -1) {
          r = find(nextV, 0);
          if (r < n) {
            const candidate = orderV[r];
            if (v[candidate] < cv - d) q = candidate;
          }
        }

        if (q === -1) {
          r = find(prevV, n);
          if (r > 0) {
            const candidate = orderV[r - 1];
            if (v[candidate] > cv + d) q = candidate;
          }
        }

        if (q === -1) break;

        color[q] = opposite;
        queue[tail++] = q;
        removePoint(q);
      }
    }
  }

  let loU = [Infinity, Infinity];
  let hiU = [-Infinity, -Infinity];
  let loV = [Infinity, Infinity];
  let hiV = [-Infinity, -Infinity];

  for (let i = 0; i < n; i++) {
    const c = color[i];
    if (u[i] < loU[c]) loU[c] = u[i];
    if (u[i] > hiU[c]) hiU[c] = u[i];
    if (v[i] < loV[c]) loV[c] = v[i];
    if (v[i] > hiV[c]) hiV[c] = v[i];
  }

  for (let c = 0; c < 2; c++) {
    if (hiU[c] - loU[c] > d || hiV[c] - loV[c] > d) return false;
  }
  return true;
}

let low = 0;
let high = Math.max(maxU - minU, maxV - minV);

while (low < high) {
  const mid = Math.floor((low + high) / 2);
  if (feasible(mid)) high = mid;
  else low = mid + 1;
}

